         => Parsers = (parser1, parser2);
+
     protected internal override ParseResult<(T1, T2)> ParseCore(Cursol cursol)
+        => ParseAndConvert(cursol, static (first, second) => (first, second));
+
+    /// <remarks>
+    /// 子の解析順序と失敗時の巻き戻しを共通化したまま、成功値から最終結果を直接作ります。
+    /// Sequence3では、入れ子のParseResultを返してから平坦化する受け渡しを省くために使います。
+    /// Sequence3からは、自身が生成した正確なSequence2型にだけこの非virtual入口を使います。
+    /// 利用者から受け取った派生パーサーのParseCoreを迂回する目的には使いません。
+    /// </remarks>
+    internal ParseResult<TResult> ParseAndConvert<TResult>(
+        Cursol cursol,
+        Func<T1, T2, TResult> converter)
+        where TResult : notnull
     {
         var result1 = Parsers.Item1.ParseCore(cursol);
         if (!result1.IsSuccess)
         {
-            return ParseResult<(T1, T2)>.Failure(cursol);
+            return ParseResult<TResult>.Failure(cursol);
         }

