# Add self-contained replay, validation, and selected JIT excerpts to the ignored evidence JSON.
# This intentionally reads source/patch identity only from the already frozen parent-validation.json,
# never from the mutable repository worktree.
#requires -Version 7.0
$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$repo = (Resolve-Path (Join-Path $root '../..')).Path
$evidencePath = Join-Path $root 'parent-validation.json'
$evidence = Get-Content -LiteralPath $evidencePath -Raw | ConvertFrom-Json
function Get-Sha256([string]$Path) { (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash }
function Get-Json([string]$Path) { Get-Content -LiteralPath (Join-Path $root $Path) -Raw | ConvertFrom-Json }
function Get-FileText([string]$Path) { [IO.File]::ReadAllText((Join-Path $root $Path)) }
function Get-AsmExcerpt([string]$Variant, [string]$Capture, [int]$Start, [int]$End, [int]$HeaderStart = 0, [int]$HeaderEnd = 0) {
    $relative = "diagnostics/jit/$Variant/$Capture/jit.asm"
    $path = Join-Path $root $relative
    $lines = [IO.File]::ReadAllLines($path)
    if ($Start -lt 1 -or $End -gt $lines.Length -or $Start -gt $End) { throw "Invalid frozen JIT range: $relative $Start-$End" }
    $text = [string]::Join("`n", $lines[($Start - 1)..($End - 1)])
    if ($HeaderStart -eq 0) {
        $nonEmptyTail = @($lines[($Start - 1)..($End - 1)] | Where-Object { $_.Trim().Length -gt 0 } | Select-Object -Last 1)
        if ($lines[$Start - 1] -notmatch '^; Assembly listing for method ' -or $nonEmptyTail.Count -ne 1 -or $nonEmptyTail[0] -notmatch '^; Total bytes of code ') { throw "Expected whole method header-to-end range not found: $relative $Start-$End" }
    } else {
        if ($lines[$HeaderStart - 1] -notmatch '^; Assembly listing for method ' -or $lines[$HeaderEnd - 1] -notmatch 'optimized using Synthesized PGO') { throw "Method header/PGO context mismatch: $relative $HeaderStart-$HeaderEnd" }
    }
    [ordered]@{
        OriginalPath = $relative
        OriginalSHA256 = Get-Sha256 $path
        OriginalLineRange = "${Start}-${End}"
        MethodHeaderContextLineRange = if ($HeaderStart) { "${HeaderStart}-${HeaderEnd}" } else { $null }
        MethodHeaderContext = if ($HeaderStart) { [string]::Join("`n", $lines[($HeaderStart - 1)..($HeaderEnd - 1)]) } else { $null }
        Excerpt = $text
    }
}

$scriptFiles = @(Get-ChildItem -LiteralPath (Join-Path $root 'scripts') -Filter '*.ps1' -File | Sort-Object Name)
$scripts = @(
    foreach ($scriptFile in $scriptFiles) {
        $relative = "scripts/$($scriptFile.Name)"
        $scriptText = [IO.File]::ReadAllText($scriptFile.FullName)
        [ordered]@{ Path = $relative; SHA256 = Get-Sha256 $scriptFile.FullName; Role = if ($scriptFile.Name -eq 'Build-ParentValidation.ps1') { 'original evidence assembly, after benchmark runs' } elseif ($scriptFile.Name -eq 'Append-FinalEvidence.ps1') { 'final evidence supplement only' } else { 'experiment preparation, validation, diagnostics, timing, or summary; exact role is evident from script name' }; Text = $scriptText }
    }
)
$scriptCount = $scripts.Count
if ($scriptCount -lt 10) { throw "Expected at least ten preserved experiment/evidence scripts; found $scriptCount." }

$manifestNames = @('baseline-source-manifest.json','candidate-source-manifest.json','baseline-dll-manifest.json','dll-manifest.json')
$manifests = [ordered]@{}
foreach ($name in $manifestNames) {
    $path = Join-Path $root $name
    $manifests[$name] = [ordered]@{ Path = $name; SHA256 = Get-Sha256 $path; Text = Get-FileText $name }
}

$runAudit = @(
    foreach ($pair in $evidence.Timing.Pairs) {
        foreach ($run in @($pair.Baseline, $pair.Candidate)) {
            if ($run.ActualCount -ne 8 -or $run.ResultCount -ne 8 -or $run.ActualIterations.Count -ne 8 -or $run.ResultIterations.Count -ne 8) { throw "Incomplete iteration evidence: $($run.Run)" }
            [ordered]@{
                Run = $run.Run; Batch = $run.Batch; Variant = $run.Variant; Order = $pair.Order
                ActualIterations = $run.ActualIterations; ResultIterations = $run.ResultIterations
                ActualCount = $run.ActualCount; ResultCount = $run.ResultCount; WarmupCount = $run.WarmupCount
                GC = $run.GC; AllocatedBytesPerOperation = $run.AllocatedBytesPerOperation
                Job = $run.Job; TieredPGO = $run.TieredPGO; Affinity = $run.Affinity
                InvocationCount = 4; UnrollFactor = 1; OutlierMode = 'DontRemove'
                ExitCode = $run.ExitCode; ProcessId = $run.ProcessId; StartUTC = $run.StartUTC; EndUTC = $run.EndUTC
                InputBytes = $run.InputBytes; InputSHA256 = $run.InputSHA256
                LibraryDLLSHA256 = $run.LibraryDLLSHA256; AssemblySHA256 = $run.AssemblySHA256
                MeasurementHostAssemblySHA256 = $run.MeasurementHostAssemblySHA256
            }
        }
    }
)

$jitExcerpts = @(
    Get-AsmExcerpt 'baseline' 'capture-02' 42162 42281
    Get-AsmExcerpt 'baseline' 'capture-02' 42302 42647
    Get-AsmExcerpt 'candidate' 'capture-01' 40125 40609
    Get-AsmExcerpt 'candidate' 'capture-01' 46013 46240
    Get-AsmExcerpt 'baseline' 'capture-02' 50355 50415 49796 49800
    Get-AsmExcerpt 'candidate' 'capture-01' 50521 50590 49706 49710
)

$baselineHost = Join-Path $root 'baseline/host'
$candidateHost = Join-Path $root 'candidate/host'
$hostArtifacts = @(
    foreach ($name in @('StringExecutionRecovery.ChildHarness.dll','StringExecutionRecovery.Measurement.dll')) {
        $basePath = Join-Path $baselineHost $name
        $candidatePath = Join-Path $candidateHost $name
        $baseHash = Get-Sha256 $basePath
        $candidateHash = Get-Sha256 $candidatePath
        if ($baseHash -ne $candidateHash) { throw "Host harness mismatch: $name" }
        [ordered]@{ Name = $name; BaselineSHA256 = $baseHash; CandidateSHA256 = $candidateHash; Identical = $true }
    }
)

$supplement = [ordered]@{
    Decision = [ordered]@{
        Overall = 'Not adopted; independent confirmation not run.'
        PerformanceConclusion = 'Improvement, regression, or equivalence cannot be established from this exploration interval.'
        IntervalRule = 'Exploration 95% paired log-t upper limit must be below 1 to authorize independent confirmation; observed upper limit is 1.0395026264148215.'
        JitObservations = 'Additional delegate/cache costs were observed in candidate code, but their timing contribution was not isolated; no speed inference is made from disassembly or code size.'
    }
    ScriptFiles = $scripts
    ScriptFileCount = $scriptCount
    ScriptUseBreakdown = [ordered]@{
        MeasurementAndReplayScripts = @('Freeze-SourceManifest.ps1','Prepare-BaselineManifest.ps1','Freeze-DllManifest.ps1','Validate-Host.ps1','Run-JitDiagnostic.ps1','Test-PowerReadiness.ps1','Record-Environment.ps1','Run-Block.ps1','Summarize.ps1')
        OriginalEvidenceAssembler = 'Build-ParentValidation.ps1; used after the measurement batch to freeze its patch and run records.'
        CurrentSupplementAssembler = 'Append-FinalEvidence.ps1; used only for this non-measurement evidence supplement.'
        Explanation = 'Ten scripts were used before this final supplement (nine experiment preparation/validation/measurement scripts plus the original evidence assembler); all eleven present scripts and hashes are included so the final evidence itself can also be reconstructed.'
    }
    SourceAndDLLManifests = $manifests
    PerRunIterationGcAndConfigurationAudit = $runAudit
    JitExcerpts = $jitExcerpts
    HostReproductionEvidence = [ordered]@{
        SourceEvidence = 'No Git evidence JSON containing the generated Measurement/ChildHarness source was found in this experiment root or the two referenced prior experiment roots. Reproduction depends on the frozen local host artifacts; their binary hashes are recorded below and in every run summary.'
        RelativeHostRoots = @('baseline/host','candidate/host')
        GeneratedHostAssemblies = $hostArtifacts
        SourceManifestScope = 'The source manifests cover repository source/build files at baseline and candidate freeze points, not the generated BenchmarkDotNet Measurement/ChildHarness source.'
    }
    PathPolicy = 'All stored paths are repository/artifact-relative; personal absolute paths are omitted.'
}
$evidence | Add-Member -NotePropertyName SupplementalEvidence -NotePropertyValue $supplement -Force
$evidence | ConvertTo-Json -Depth 24 | Set-Content -LiteralPath $evidencePath -Encoding utf8
Write-Output ('Updated parent-validation.json; {0} scripts, {1} manifests, {2} runs, {3} JIT excerpts; SHA256 {4}' -f $scriptCount,$manifests.Count,$runAudit.Count,$jitExcerpts.Count,(Get-Sha256 $evidencePath))

# Freeze the performance experiment, validation, and four-file source patch into one ignored evidence JSON.
#requires -Version 7.0
$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$repo = (Resolve-Path (Join-Path $root '../..')).Path
function Read-Json([string]$Path) { Get-Content -LiteralPath (Join-Path $root $Path) -Raw | ConvertFrom-Json }
function Hash-File([string]$Path) { (Get-FileHash -LiteralPath (Join-Path $repo $Path) -Algorithm SHA256).Hash }

$sourceAndTestPaths = @(
    'Kotowari/Core/SequenceParser2.cs',
    'Kotowari/Core/SequenceParser3.cs',
    'Kotowari.Tests/Core/要素を2つ持つSeqenceParserのテスト.cs',
    'Kotowari.Tests/Core/要素を3つ持つSeqenceParserのテスト.cs'
)
$patch = (& git -C $repo diff --binary --unified=3 -- @sourceAndTestPaths) -join "`n"
if ($LASTEXITCODE -ne 0 -or [string]::IsNullOrWhiteSpace($patch)) { throw 'Could not capture the requested four-file source/test patch.' }
$patchHash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.UTF8Encoding]::new($false).GetBytes($patch)))
$candidateManifestPath = Join-Path $root 'candidate-source-manifest.json'
$candidateManifestHash = (Get-FileHash -LiteralPath $candidateManifestPath -Algorithm SHA256).Hash
$baselineManifestPath = Join-Path $root 'baseline-source-manifest.json'
$baselineManifestHash = (Get-FileHash -LiteralPath $baselineManifestPath -Algorithm SHA256).Hash
$dllManifestPath = Join-Path $root 'dll-manifest.json'
$dllManifestHash = (Get-FileHash -LiteralPath $dllManifestPath -Algorithm SHA256).Hash

$pairRecords = @()
for ($block = 1; $block -le 8; $block++) {
    $pairRecords += [ordered]@{
        Block = $block
        Order = if ($block % 2) { 'baseline-candidate' } else { 'candidate-baseline' }
        Baseline = Read-Json ("runs/exploration/{0:d2}-baseline/run-summary.json" -f $block)
        Candidate = Read-Json ("runs/exploration/{0:d2}-candidate/run-summary.json" -f $block)
    }
}
$jitBaseline = Read-Json 'diagnostics/jit/baseline/capture-02/capture.json'
$jitCandidate = Read-Json 'diagnostics/jit/candidate/capture-01/capture.json'
$sourceHashes = @(
    foreach ($path in $sourceAndTestPaths) { [ordered]@{ Path = $path; SHA256 = Hash-File $path } }
)
$environment = Read-Json 'environment.json'
$evidence = [ordered]@{
    Experiment = '2026-10-20-string-sequence3-projection'
